function analyze(text){
  text=String(text);
  var chars=text.length;
  var noSpace=text.replace(/\s/g,'').length;
  var latin=(text.match(/[A-Za-z0-9]+/g)||[]).length;
  var cjk=(text.match(/[㐀-鿿豈-﫿]/g)||[]).length;
  var lines=text.length? text.split(/\n/).length : 0;
  var sentences=(text.match(/[.!?。！？…]+/g)||[]).length;
  var paras=text.split(/\n\s*\n/).filter(function(p){return p.replace(/\s/g,'').length;}).length;
  var readingMin=Math.max(0.1, Math.round((cjk/300 + latin/200)*10)/10);
  return {chars:chars,noSpace:noSpace,latin:latin,cjk:cjk,lines:lines,sentences:sentences,paragraphs:paras,readingMin:readingMin};
}
function topWords(text, n){
  var m=text.toLowerCase().match(/[a-z0-9]+/g)||[];
  var f={}; m.forEach(function(w){f[w]=(f[w]||0)+1;});
  var arr=Object.keys(f).map(function(k){return [k,f[k]];});
  arr.sort(function(a,b){return b[1]-a[1];});
  return arr.slice(0, n||10);
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports={analyze:analyze,topWords:topWords};
}
if (typeof window !== 'undefined') {
  window.WordForgePure={analyze:analyze,topWords:topWords};
}
